"use client"

import * as React from "react"
import { Toast as ToastPrimitive } from "@base-ui/react/toast"
import { cn } from "@/lib/utils"
import { X, CheckCircle2, XCircle, AlertTriangle, Info, Loader2 } from "lucide-react"

import "@/styles/feedback.styles.css"

type ToastPosition =
  | "top-left"
  | "top-center"
  | "top-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right"

interface ToastContextValue {
  position: ToastPosition
}

const ToastContext = React.createContext<ToastContextValue>({
  position: "bottom-right",
})

function useToast() {
  return ToastPrimitive.useToastManager()
}

const viewportPositionStyles: Record<ToastPosition, string> = {
  "top-left": "top-4 left-4 sm:top-6 sm:left-6",
  "top-center": "top-4 left-1/2 -translate-x-1/2 sm:top-6",
  "top-right": "top-4 right-4 sm:top-6 sm:right-6",
  "bottom-left": "bottom-4 left-4 sm:bottom-6 sm:left-6",
  "bottom-center": "bottom-4 left-1/2 -translate-x-1/2 sm:bottom-6",
  "bottom-right": "bottom-4 right-4 sm:bottom-6 sm:right-6",
}

const typeIcon: Record<string, React.ReactNode> = {
  success: <CheckCircle2 className="size-5 text-success shrink-0" />,
  error: <XCircle className="size-5 text-destructive shrink-0" />,
  warning: <AlertTriangle className="size-5 text-warning shrink-0" />,
  info: <Info className="size-5 text-info shrink-0" />,
  loading: (
    <Loader2 className="size-5 text-muted-foreground shrink-0 animate-spin motion-reduce:animate-none" />
  ),
}

function ToastViewport({
  className,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Viewport>) {
  const { position } = React.useContext(ToastContext)
  return (
    <ToastPrimitive.Viewport
      className={cn(
        "toast-viewport-layout fixed z-100 flex flex-col outline-none",
        viewportPositionStyles[position],
        className
      )}
      {...props}
    />
  )
}

const sharedRootClasses = [
  "group",
  "[--gap:0.75rem]",
  "[--peek:0.75rem]",
  "[--scale:calc(max(0,1-(var(--toast-index)*0.1)))]",
  "[--shrink:calc(1-var(--scale))]",
  "[--height:var(--toast-frontmost-height,var(--toast-height))]",
  "absolute left-auto z-[calc(1000-var(--toast-index))] mr-0 w-full",
  "h-[var(--height)]",
  "toast-root-layout border border-border bg-popover text-popover-foreground select-none bg-clip-padding",
  "[transition:transform_220ms_ease-out,opacity_160ms_ease-out,height_160ms_ease-out] motion-reduce:transition-none",
  "data-[ending-style]:opacity-0",
  "data-[limited]:opacity-0",
  "data-[expanded]:h-[var(--toast-height)]",
  "after:absolute after:left-0 after:h-[calc(var(--gap)+1px)] after:w-full after:content-['']",
]

const bottomClasses = [
  ...sharedRootClasses,
  "right-0 bottom-0 origin-bottom",
  "after:top-full",
  "[--offset-y:calc(var(--toast-offset-y)*-1+calc(var(--toast-index)*var(--gap)*-1)+var(--toast-swipe-movement-y))]",
  "[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)-(var(--toast-index)*var(--peek))-(var(--shrink)*var(--height))))_scale(var(--scale))]",
  "data-[starting-style]:[transform:translateY(150%)]",
  "[&[data-ending-style]:not([data-limited]):not([data-swipe-direction])]:[transform:translateY(150%)]",
  "data-[expanded]:[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--offset-y)))]",
  "data-[ending-style]:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
  "data-[ending-style]:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
  "data-[ending-style]:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
  "data-[ending-style]:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
]

const topClasses = [
  ...sharedRootClasses,
  "right-0 top-0 origin-top",
  "after:bottom-full",
  "[--offset-y:calc(var(--toast-offset-y)+calc(var(--toast-index)*var(--gap))+var(--toast-swipe-movement-y))]",
  "[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)+(var(--toast-index)*var(--peek))+(var(--shrink)*var(--height))))_scale(var(--scale))]",
  "data-[starting-style]:[transform:translateY(-150%)]",
  "[&[data-ending-style]:not([data-limited]):not([data-swipe-direction])]:[transform:translateY(-150%)]",
  "data-[expanded]:[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--offset-y)))]",
  "data-[ending-style]:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
  "data-[ending-style]:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
  "data-[ending-style]:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
  "data-[ending-style]:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
  "data-[expanded]:data-[ending-style]:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
]

function ToastRoot({ toast, className, ...props }: ToastPrimitive.Root.Props) {
  const { position } = React.useContext(ToastContext)
  const isTop = position.startsWith("top")

  return (
    <ToastPrimitive.Root
      toast={toast}
      className={cn(isTop ? topClasses : bottomClasses, className)}
      {...props}
    />
  )
}

function ToastContent({
  className,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Content>) {
  return (
    <ToastPrimitive.Content
      className={cn(
        "overflow-hidden transition-opacity duration-160 motion-reduce:transition-none",
        "data-[behind]:pointer-events-none data-[behind]:opacity-0",
        "data-[expanded]:pointer-events-auto data-[expanded]:opacity-100",
        className
      )}
      {...props}
    />
  )
}

function ToastTitle({ className, ...props }: React.ComponentProps<typeof ToastPrimitive.Title>) {
  return <ToastPrimitive.Title className={cn("toast-title-layout", className)} {...props} />
}

function ToastDescription({
  className,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Description>) {
  return (
    <ToastPrimitive.Description className={cn("toast-description-layout", className)} {...props} />
  )
}

function ToastAction({ className, ...props }: React.ComponentProps<typeof ToastPrimitive.Action>) {
  return <ToastPrimitive.Action className={cn("toast-action-layout", className)} {...props} />
}

function ToastClose({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Close>) {
  return (
    <ToastPrimitive.Close
      className={cn("toast-close-layout", className)}
      aria-label="Close"
      {...props}
    >
      {children ?? <X className="size-4" />}
    </ToastPrimitive.Close>
  )
}

function getToastIcon(toast: ToastPrimitive.Root.ToastObject): React.ReactNode {
  if (toast.type && toast.type in typeIcon) {
    return typeIcon[toast.type]
  }
  return null
}

function ToastList() {
  const { toasts } = ToastPrimitive.useToastManager()
  return toasts.map((toast) => {
    const icon = getToastIcon(toast)
    return (
      <ToastRoot key={toast.id} toast={toast}>
        <ToastContent className="flex items-start gap-3">
          {icon && <div className="mt-0.5">{icon}</div>}
          <div className="flex min-w-0 flex-1 flex-col gap-1 pe-6">
            <ToastTitle />
            <ToastDescription />
            {toast.actionProps && (
              <div className="mt-2">
                <ToastAction />
              </div>
            )}
          </div>
          <ToastClose />
        </ToastContent>
      </ToastRoot>
    )
  })
}

interface ToastProviderProps {
  children: React.ReactNode
  position?: ToastPosition
  limit?: number
  toastManager?: ReturnType<typeof ToastPrimitive.createToastManager>
}

function ToastProvider({
  children,
  position = "bottom-right",
  limit = 5,
  toastManager,
}: ToastProviderProps) {
  const ctx = React.useMemo(() => ({ position }), [position])

  return (
    <ToastContext.Provider value={ctx}>
      <ToastPrimitive.Provider limit={limit} {...(toastManager ? { toastManager } : {})}>
        {children}
        <ToastPrimitive.Portal>
          <ToastViewport>
            <ToastList />
          </ToastViewport>
        </ToastPrimitive.Portal>
      </ToastPrimitive.Provider>
    </ToastContext.Provider>
  )
}

const createToastManager = ToastPrimitive.createToastManager

export {
  ToastProvider,
  ToastViewport,
  ToastRoot,
  ToastContent,
  ToastTitle,
  ToastDescription,
  ToastAction,
  ToastClose,
  ToastList,
  useToast,
  createToastManager,
  typeIcon,
}
export type { ToastPosition, ToastProviderProps }

/* Feedback anatomy. Status colors come from the consumer's existing theme. */
@layer components {
  .alert-layout {
    --alert-status: var(--border);
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: calc(4 * var(--component-unit, 0.0625rem)) calc(12 * var(--component-unit, 0.0625rem));
    position: relative;
    width: 100%;
    border: 1px solid var(--alert-status);
    border-radius: var(--radius, 0.625rem);
    padding: calc(16 * var(--component-unit, 0.0625rem));
    background: var(--card);
    color: var(--card-foreground);
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
  }
  .alert-layout:has(> svg) {
    grid-template-columns: calc(16 * var(--component-unit, 0.0625rem)) minmax(0, 1fr) auto;
  }
  .alert-layout > svg {
    grid-column: 1;
    grid-row: 1 / 3;
    width: calc(16 * var(--component-unit, 0.0625rem));
    height: calc(20 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .alert-layout:is(
    .alert-destructive-layout,
    .alert-info-layout,
    .alert-success-layout,
    .alert-warning-layout
  ) {
    border-color: color-mix(in srgb, var(--alert-status) 35%, var(--border));
  }
  .alert-layout:is(
      .alert-destructive-layout,
      .alert-info-layout,
      .alert-success-layout,
      .alert-warning-layout
    )
    > svg {
    color: var(--alert-status);
  }
  .alert-destructive-layout {
    --alert-status: var(--destructive);
  }
  .alert-info-layout {
    --alert-status: var(--info);
  }
  .alert-success-layout {
    --alert-status: var(--success);
  }
  .alert-warning-layout {
    --alert-status: var(--warning);
  }
  .alert-title-layout,
  .alert-description-layout {
    grid-column: 1;
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .alert-layout:has(> svg) > :is(.alert-title-layout, .alert-description-layout) {
    grid-column: 2;
  }
  .alert-title-layout {
    font-weight: 600;
  }
  .alert-description-layout {
    display: flex;
    flex-direction: column;
    gap: calc(8 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .alert-action-layout {
    display: flex;
    flex-wrap: wrap;
    gap: calc(8 * var(--component-unit, 0.0625rem));
    grid-column: -2;
    grid-row: 1 / 3;
    align-self: center;
  }
  .toast-viewport-layout {
    width: min(calc(384 * var(--component-unit, 0.0625rem)), calc(100vw - 32px));
    max-width: calc(100vw - 32px);
  }
  .toast-root-layout {
    padding: calc(16 * var(--component-unit, 0.0625rem));
    border-radius: var(--radius, 0.625rem);
    box-shadow: 0 6px 18px rgb(0 0 0 / 0.12);
  }
  .dark .toast-root-layout {
    box-shadow: 0 6px 18px rgb(0 0 0 / 0.2);
  }
  .toast-title-layout,
  .toast-description-layout {
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
    overflow-wrap: anywhere;
  }
  .toast-title-layout {
    font-weight: 600;
  }
  .toast-description-layout {
    color: var(--muted-foreground);
  }
  .toast-action-layout,
  .toast-close-layout {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: max(0px, calc(var(--radius, 0.625rem) - 4px));
    outline: none;
    transition:
      background-color 100ms,
      color 100ms;
  }
  .toast-action-layout {
    min-height: calc(32 * var(--component-unit, 0.0625rem));
    padding: calc(4 * var(--component-unit, 0.0625rem)) calc(12 * var(--component-unit, 0.0625rem));
    border: 1px solid var(--input);
    background: transparent;
    color: var(--foreground);
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
    font-weight: 500;
  }
  .toast-close-layout {
    position: absolute;
    inset-block-start: calc(8 * var(--component-unit, 0.0625rem));
    inset-inline-end: calc(8 * var(--component-unit, 0.0625rem));
    width: calc(28 * var(--component-unit, 0.0625rem));
    height: calc(28 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .toast-action-layout:focus-visible,
  .toast-close-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
    box-shadow: none;
  }
  .toast-action-layout:disabled,
  .toast-close-layout:disabled {
    color: var(--muted-foreground);
    cursor: not-allowed;
  }
  .progress-layout {
    display: flex;
    flex-wrap: wrap;
    gap: calc(8 * var(--component-unit, 0.0625rem));
  }
  .progress-track-layout {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    height: calc(4 * var(--component-unit, 0.0625rem));
    overflow: hidden;
    border-radius: 999px;
    background: var(--muted);
  }
  .progress-indicator-layout {
    height: 100%;
    background: var(--primary);
    transition: width 160ms ease-out;
  }
  .progress-indicator-layout[data-indeterminate] {
    width: 40%;
    animation: feedback-progress 1.4s ease-in-out infinite;
  }
  .progress-label-layout,
  .progress-value-layout {
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
  }
  .progress-label-layout {
    font-weight: 500;
  }
  .progress-value-layout {
    margin-inline-start: auto;
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }
  @media (hover: hover) {
    .toast-action-layout:not(:disabled):hover,
    .toast-close-layout:not(:disabled):hover {
      background: var(--muted);
      color: var(--foreground);
    }
  }
  @media (max-width: 639px) {
    .alert-action-layout {
      grid-column: 1 / -1;
      grid-row: auto;
      margin-block-start: calc(8 * var(--component-unit, 0.0625rem));
    }
    .alert-layout:has(> svg) > .alert-action-layout {
      grid-column: 2 / -1;
    }
  }
  @media (pointer: coarse) {
    .toast-action-layout,
    .toast-close-layout {
      min-width: 44px;
      min-height: 44px;
    }
    .toast-root-layout {
      padding-inline-end: 28px;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .toast-root-layout,
    .toast-action-layout,
    .toast-close-layout,
    .progress-indicator-layout {
      transition: none;
    }
    .progress-indicator-layout[data-indeterminate] {
      animation: none;
    }
  }
  @media (forced-colors: active) {
    .alert-layout {
      border-color: CanvasText;
    }
    .toast-action-layout:focus-visible,
    .toast-close-layout:focus-visible {
      outline-color: Highlight;
    }
    .progress-track-layout {
      border: 1px solid CanvasText;
    }
    .progress-indicator-layout {
      background: Highlight;
    }
  }
}
@keyframes feedback-progress {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(350%);
  }
}
